  perform private.mark_missing_attendance('2026-09-29 09:00 America/Port-au-Prince');
  if not exists(select 1 from public.attendance where student_id=child1 and attendance_date='2026-09-29' and status='late' and check_in_at is not null) then raise exception 'TEST existing check-in overwritten';end if;
